import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.InputStream;
import java.util.Set;
import java.util.TreeSet;

public class CF933C_V1 {
    public static final double EPSILON = 1e-10;
    static final boolean IS_ONLINE_JUDGE = System.getProperty("ONLINE_JUDGE") != null;
    public static BlockReader input;

    public static void main(String[] args) throws FileNotFoundException {
        if (!IS_ONLINE_JUDGE) {
            System.setIn(new FileInputStream("D:\\DataBase\\TESTCASE\\codeforces\\CF933C.in"));
        }
        input = new BlockReader(System.in);
        compute();
    }

    public static void compute() {
        int n = input.nextInteger();
        Circle[] circles = new Circle[n];

        for (int i = 0; i < n; i++) {
            circles[i] = new Circle(input.nextInteger(), input.nextInteger(), input.nextInteger());
        }

        if (n == 3 && !Circle.doIntersect(circles[0], circles[1])) {
            int count = 4;
            if (Circle.doIntersect2(circles[0], circles[2])) {
                count++;
            }
            if (Circle.doIntersect2(circles[1], circles[2])) {
                count++;
            }
            System.out.println(count);
            return;
        }

        int total = 1;
        TreeSet<Point> points = new TreeSet<>();
        for (int i = 0; i < n; i++) {
            points.clear();
            total++;
            for (int j = 0; j < i; j++) {
                Circle.computeIntersections(circles[i], circles[j], points);
            }
            if (points.size() >= 2) {
                total += points.size() - 1;
            }
        }

        System.out.println(total);
    }

    public static double dist(Point a, Point b) {
        return Math.sqrt(distSq(a, b));
    }

    public static double distSq(Point a, Point b) {
        double dx = a.x - b.x;
        double dy = a.y - b.y;
        return dx * dx + dy * dy;
    }

    public static class Circle {
        Point center;
        int radius;

        public Circle(int x, int y, int r) {
            this.center = new Point(x, y);
            this.radius = r;
        }

        public static boolean doIntersect(Circle a, Circle b) {
            double d = dist(a.center, b.center);
            return d <= a.radius + b.radius + EPSILON && d + EPSILON >= Math.abs(a.radius - b.radius);
        }

        public static boolean doIntersect2(Circle a, Circle b) {
            double d = dist(a.center, b.center);
            return d < a.radius + b.radius && d > Math.abs(a.radius - b.radius);
        }

        public static void computeIntersections(Circle a, Circle b, Set<Point> set) {
            if (!doIntersect(a, b)) {
                return;
            }

            Line line = new Line(a.center, b.center);
            double d = dist(a.center, b.center);
            double middleDist = (d * d - b.radius * b.radius + a.radius * a.radius) / (2 * d);
            Point midPoint = a.center.translate(line, middleDist);
            Point direction = line.asDirection().perpendicular();
            double height = Math.sqrt(a.radius * a.radius - middleDist * middleDist);
            Point first = midPoint.translate(direction, height);
            Point second = midPoint.translate(direction, -height);

            set.add(first);
            if (!second.equals(first)) {
                set.add(second);
            }
        }
    }

    public static class Point implements Comparable<Point> {
        double x, y;

        public Point(double x, double y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public String toString() {
            return "(" + x + "," + y + ")";
        }

        public Point subtract(Point other) {
            return new Point(x - other.x, y - other.y);
        }

        public Point translate(Line line, double length) {
            return translate(line.asDirection(), length);
        }

        public Point translate(Point vec, double length) {
            Point normalized = vec.normalize();
            return add(normalized.multiply(length));
        }

        public Point add(Point other) {
            return new Point(x + other.x, y + other.y);
        }

        public Point multiply(double factor) {
            return new Point(x * factor, y * factor);
        }

        public Point normalize() {
            double len = Math.sqrt(x * x + y * y);
            return divide(len);
        }

        public Point divide(double factor) {
            return new Point(x / factor, y / factor);
        }

        public Point perpendicular() {
            return new Point(-y, x);
        }

        @Override
        public boolean equals(Object obj) {
            Point other = (Point) obj;
            return Math.abs(x - other.x) < EPSILON && Math.abs(y - other.y) < EPSILON;
        }

        @Override
        public int compareTo(Point o) {
            if (equals(o)) {
                return 0;
            }
            if (Math.abs(x - o.x) < EPSILON) {
                return Double.compare(y, o.y);
            }
            return Double.compare(x, o.x);
        }
    }

    public static class Line {
        Point start;
        Point end;

        public Line(Point start, Point end) {
            this.start = start;
            this.end = end;
        }

        public Point asDirection() {
            return end.subtract(start);
        }

        public double length() {
            return dist(start, end);
        }
    }

    public static class BlockReader {
        static final int EOF = -1;
        InputStream is;
        byte[] buffer;
        int pos, size, next;
        StringBuilder builder = new StringBuilder();

        public BlockReader(InputStream is) {
            this(is, 4096);
        }

        public BlockReader(InputStream is, int bufSize) {
            this.is = is;
            buffer = new byte[bufSize];
            next = nextByte();
        }

        public int nextByte() {
            while (pos >= size) {
                if (size == -1) {
                    return EOF;
                }
                pos = 0;
                try {
                    size = is.read(buffer);
                } catch (Exception e) {
                }
            }
            return buffer[pos++];
        }

        public String nextToken() {
            builder.setLength(0);
            skipWhitespace();
            while (next != EOF && !Character.isWhitespace(next)) {
                builder.append((char) next);
                next = nextByte();
            }
            return builder.toString();
        }

        public void skipWhitespace() {
            while (Character.isWhitespace(next)) {
                next = nextByte();
            }
        }

        public int nextInteger() {
            skipWhitespace();
            int result = 0;
            boolean negative = false;
            if (next == '+' || next == '-') {
                negative = next == '-';
                next = nextByte();
            }
            while (next >= '0' && next <= '9') {
                result = (result << 3) + (result << 1) + next - '0';
                next = nextByte();
            }
            return negative ? -result : result;
        }

        public int nextToken(char[] data, int offset) {
            skipWhitespace();
            int index = offset;
            int bound = data.length;
            while (next != EOF && index < bound && !Character.isWhitespace(next)) {
                data[index++] = (char) next;
                next = nextByte();
            }
            return index - offset;
        }

        public boolean hasMore() {
            skipWhitespace();
            return next != EOF;
        }
    }
}
